            if a > b:
                a, b = b, a
            pairs.append(f"({a}, {b})")
        if pairs:
            return AnswerDecision.redirect("\n".join(pairs))

    # Accept as-is if nothing matched (e.g., empty or unrecognizable)
    return AnswerDecision.accept(answer)

